import ch.jalu.configme.exception.ConfigMeException;
import ch.jalu.configme.properties.Property;
import org.junit.Test;
import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

public class PropertyListBuilderTest {

    @Test
    public void addTest() {
        Property<String> propertyOne = new Property<>("property.one", "default");
        Property<String> propertyTwo = new Property<>("property.two", "default");

        PropertyListBuilder builder = new PropertyListBuilder();
        builder.add(propertyOne);
        builder.add(propertyTwo);

        Map<String, Object> rootEntries = builder.getRootEntries();
        assertEquals(1, rootEntries.size());
        assertTrue(rootEntries.get("property") instanceof Map);
    }

    @Test
    public void addSamePropertyTwiceTest() {
        Property<String> property = new Property<>("property", "default");

        PropertyListBuilder builder = new PropertyListBuilder();
        builder.add(property);

        try {
            builder.add(property);
            fail("Expected ConfigMeException");
        } catch (ConfigMeException e) {
            assertEquals("Path at 'property' already exists", e.getMessage());
        }
    }

    @Test
    public void addNestedPropertiesTest() {
        Property<String> propertyOne = new Property<>("property.one", "default");
        Property<String> propertyTwo = new Property<>("property.two", "default");

        PropertyListBuilder builder = new PropertyListBuilder();
        builder.add(propertyOne);
        builder.add(propertyTwo);

        List<Property<?>> properties = builder.create();
        assertEquals(2, properties.size());
        assertEquals("property.one", properties.get(0).getPath());
        assertEquals("property.two", properties.get(1).getPath());
    }

    @Test
    public void addIncompatibleNestedPropertiesTest() {
        Property<String> propertyGroup = new Property<>("property", "default");
        Property<String> propertyNested = new Property<>("property.nested", "default");

        PropertyListBuilder builder = new PropertyListBuilder();
        builder.add(propertyGroup);

        try {
            builder.add(propertyNested);
            fail("Expected ConfigMeException");
        } catch (ConfigMeException e) {
            assertEquals("Unexpected entry found at path 'property'", e.getMessage());
        }
    }

    @Test
    public void addPropertiesInDifferentNestedGroupsTest() {
        Property<String> propertyOne = new Property<>("property.one", "default");
        Property<String> propertyNested = new Property<>("propertyNested.value", "default");

        PropertyListBuilder builder = new PropertyListBuilder();
        builder.add(propertyOne);
        builder.add(propertyNested);

        List<Property<?>> properties = builder.create();
        assertEquals(2, properties.size());
        assertEquals("property.one", properties.get(0).getPath());
        assertEquals("propertyNested.value", properties.get(1).getPath());
